import React, { useState, useEffect } from 'react';
import './ProfilePage.css'; // Ensure CSS is updated
import { useNavigate } from 'react-router-dom';

const ProfilePage = () => {
  const navigate = useNavigate();

  const navigateToHome = () => navigate('/homes');
  const navigateToChat = () => navigate('/chat');
  const navigateToproj = () => navigate('/ong-proj');
  const navigateToPost = () => navigate('/post');
  const navigateContact = () => navigate('/contact');
  const navigateToAbout = () => navigate('/abt');

  const [profile, setProfile] = useState(null);
  const [isEditing, setIsEditing] = useState(false);
  const [tempProfile, setTempProfile] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const token = localStorage.getItem('token');
    if (!token) {
      setError('No authentication token found. Please log in.');
      navigate('/login');
      return;
    }

    fetch('http://localhost:5001/api/user/profile', {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`
      }
    })
      .then((res) => {
        if (!res.ok) throw new Error('Failed to fetch profile');
        return res.json();
      })
      .then((data) => {
        setProfile(data);
        setTempProfile(data);
        setLoading(false);
      })
      .catch((err) => {
        console.error('Error fetching profile:', err);
        setError('Failed to load profile');
        setLoading(false);
      });
  }, [navigate]);

  const handleEdit = () => {
    if (isEditing) {
      const token = localStorage.getItem('token');
      if (!token) {
        setError('Authentication token missing.');
        return;
      }

      const updatedProfile = { 
        email: tempProfile.email, 
        password: tempProfile.password, 
        profilePhoto: tempProfile.profilePhoto,
        bio: tempProfile.bio
      };

      fetch('http://localhost:5001/api/user/profile', {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(updatedProfile),
      })
        .then((res) => {
          if (!res.ok) throw new Error('Failed to update profile');
          return res.json();
        })
        .then((updatedProfile) => {
          setProfile(updatedProfile);
          setIsEditing(false);
        })
        .catch((err) => console.error('Error updating profile:', err));
    } else {
      setIsEditing(true);
    }
  };

  const handleChange = (field, value) => {
    setTempProfile({ ...tempProfile, [field]: value });
  };

  if (loading) return <p>Loading...</p>;
  if (error) return <p style={{ color: 'red' }}>{error}</p>;

  return (
    <div className="profile-page">
      {/* Header */}
      <div className="header">
        <img src="images/image10.png" alt="User" />
        <div className="header-right">
          <span onClick={navigateToHome}>Home</span>
          <span onClick={navigateContact}>Contact Us</span>
          <span onClick={navigateToAbout}>About</span>
          <span onClick={navigateToChat}>Chat</span>
          <span onClick={navigateToproj}>Ongoing Projects</span>
          <span onClick={navigateToPost}>Post a Job</span>
          <span>Settings</span>
        </div>
      </div>

      {/* Main Content */}
      <div className="main-content">
        {/* Profile Card */}
        <div className="profile-card">
          <div className="card-border-top"></div>
          <div className="img">
            <img src={profile.profilePhoto || 'default-user.png'} alt="User" />
          </div>
          <span>{profile.name || 'User'}</span>
          <span className="job">{profile.skills ? profile.skills.join(', ') : 'No skills listed'}</span>
          <span>Rating: {profile.rating || 'N/A'} ⭐</span>
          <button onClick={handleEdit}>{isEditing ? 'Save' : 'Edit'}</button>
        </div>

        {/* About Me Section */}
        <div className="about-me">
          <h2>About Me</h2>
          <p>{profile.bio || "No bio available."}</p>
          <h3>Skills</h3>
          <p>{profile.skills ? profile.skills.join(', ') : "No skills listed."}</p>
        </div>

        {/* Achievements (Horizontal) */}
        <div className="achievements-section">
          <h2>Achievements</h2>
          <div className="achievements-container">
            {profile.achievements && profile.achievements.length > 0 ? (
              profile.achievements.map((achievement, index) => (
                <div key={index} className="achievement-item">
                  <h3>{achievement.title}</h3>
                  <p>{achievement.description}</p>
                </div>
              ))
            ) : (
              <p>No achievements listed.</p>
            )}
          </div>
        </div>

        {/* Reviews Section */}
        <div className="reviews-section">
          <h2>Reviews Received</h2>
          <div className="reviews-card">
            {profile.reviews && profile.reviews.length > 0 ? (
              profile.reviews.map((review, index) => (
                <div key={index} className="review-item">
                  <h3>{review.reviewer || 'Anonymous'}</h3>
                  <p>"{review.comment || 'No comment'}"</p>
                  <span>{'⭐'.repeat(review.rating || 0)}</span>
                </div>
              ))
            ) : (
              <p>No reviews available.</p>
            )}
          </div>
        </div>

        {/* Edit Modal */}
        {isEditing && (
          <div className="edit-modal">
            <h2>Edit Profile</h2>
            <input type="text" value={tempProfile.name} readOnly placeholder="Full Name (Cannot be changed)" />

            <input type="email" value={tempProfile.email} onChange={(e) => handleChange('email', e.target.value)} placeholder="Email" />

            <input type="password" value={tempProfile.password} onChange={(e) => handleChange('password', e.target.value)} placeholder="New Password" />

            <input type="text" value={tempProfile.profilePhoto} onChange={(e) => handleChange('profilePhoto', e.target.value)} placeholder="Profile Photo URL" />

            <textarea value={tempProfile.bio} onChange={(e) => handleChange('bio', e.target.value)} placeholder="Tell about yourself (max 100 words)" maxLength="100" />

            <button onClick={handleEdit}>Save Changes</button>
          </div>
        )}
      </div>
    </div>
  );
};

export default ProfilePage;
